// Group tasks by Assignee (User)
const grouped = {};

for (const item of $input.all()) {
  const assignee = item.json.Assigned_To;
  const whatsappNumber = item.json.Assignee_WhatsApp;

  // Skip if no assignee
  if (!assignee) {
    continue;
  }

  // Initialize group if not exists
  if (!grouped[assignee]) {
    grouped[assignee] = {
      assignee: assignee,
      whatsapp_number: whatsappNumber,
      tasks: []
    };
  }

  // Add task details
  grouped[assignee].tasks.push({
    task_id: item.json["Task ID"],
    task_details: item.json.Task_Details,
    due_date: item.json.Due_Date,
    status: item.json.Status,
    count_followup: item.json["Count_no._of_FollowUp"] || 0,
    row_number: item.json.row_number
  });
}

// Format message for each user
const result = [];

for (const assignee in grouped) {
  const userGroup = grouped[assignee];
  const taskCount = userGroup.tasks.length;

  let message = `Hi ${assignee},\n\n`;

  if (taskCount === 1) {
    // Single task message
    const task = userGroup.tasks[0];
    message += ` *Task Due Today Reminder*\n\n`;
    message += `*Task ID:* ${task.task_id}\n`;
    message += `*Task Details:* ${task.task_details}\n`;
    message += `*Due Date:* ${task.due_date}\n`;
    message += `*Current Status:* ${task.status}\n\n`;
    message += `⏰ This task was due today. Have you completed it?\n\n`;
    message += `Please reply to this message with:\n`;
    message += ` If completed - Share a screenshot or confirmation\n`;
    message += `⏳ If in progress - Let me know your current status\n`;
    message += ` If facing issues - Share the reason and expected completion date\n\n`;
    message += `Reply here so I can update the records. Thanks! `;
  } else {
    // Multiple tasks message
    message += ` *Multiple Tasks Due Today Reminder*\n\n`;
    message += `You have *${taskCount} tasks* due today:\n\n`;

    userGroup.tasks.forEach((task, index) => {
      message += `*${index + 1}. ${task.task_id}*\n`;
      message += `    ${task.task_details}\n`;
      message += `    Due: ${task.due_date}\n`;
      message += `    Status: ${task.status}\n\n`;
    });

    message += `⏰ All these tasks were due today. Please provide status for each:\n\n`;
    message += `Reply to this message mentioning the Task ID and:\n`;
    message += ` If completed - Share confirmation\n`;
    message += `⏳ If in progress - Share current status\n`;
    message += ` If facing issues - Share reason and new expected date\n\n`;
    message += `Reply here so I can update the records. Thanks! `;
  }

  result.push({
    json: {
      assignee: userGroup.assignee,
      whatsapp_number: userGroup.whatsapp_number,
      total_tasks: taskCount,
      tasks: userGroup.tasks,
      message: message
    }
  });
}

return result;

